mapper.select:
SELECT id, ds_id, thread_id, sql_fingerprint, sql_abstract, statement_type, db_type,
       involved_tables, risk_level, verdict, block_reason,
       level_l1_result, level_l2_result, level_l3_result, level_l4_result, level_l5_result,
       levels_summary, fix_suggestion, cost_ms, result_row_count, truncated, guard_status,
       create_time, update_time, is_deleted
FROM sql_guard_audit_log
WHERE is_deleted = 0

    AND ds_id = #{dsId}


    AND thread_id = #{threadId}


    AND risk_level = #{riskLevel}


    AND verdict = #{verdict}


    AND guard_status = #{guardStatus}


    AND create_time >= #{startDate}


    AND create_time <= #{endDate}

ORDER BY create_time DESC, id DESC

SELECT COUNT(*)
FROM sql_guard_audit_log
WHERE is_deleted = 0

    AND ds_id = #{dsId}


    AND thread_id = #{threadId}


    AND risk_level = #{riskLevel}


    AND verdict = #{verdict}


    AND guard_status = #{guardStatus}


    AND create_time >= #{startDate}


    AND create_time <= #{endDate}
